<?php
require __DIR__.'/ui.php';role(['admin','gerente','caixa']);$p=db();$date=$_GET['date']??date('Y-m-d');
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();if(isset($_POST['movement']))$p->prepare("INSERT INTO cash_movements(type,description,amount,payment_method,user_id)VALUES(?,?,?,?,?)")->execute([$_POST['type'],$_POST['description'],$_POST['amount'],$_POST['payment_method'],current_user()['id']]);if(isset($_POST['close'])){$sales=(float)$p->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE date(created_at)='$date' AND status<>'Cancelado'")->fetchColumn();$mov=(float)$p->query("SELECT COALESCE(SUM(CASE WHEN type='Entrada' THEN amount ELSE -amount END),0) FROM cash_movements WHERE date(created_at)='$date'")->fetchColumn();$expected=$sales+$mov;$counted=floatval($_POST['counted']);$p->prepare("INSERT INTO cash_closings(closing_date,expected,counted,difference,notes,user_id)VALUES(?,?,?,?,?,?) ON CONFLICT(closing_date) DO UPDATE SET expected=excluded.expected,counted=excluded.counted,difference=excluded.difference,notes=excluded.notes,user_id=excluded.user_id")->execute([$date,$expected,$counted,$counted-$expected,$_POST['notes'],current_user()['id']]);}go('cash.php?date='.$date);}
$sales=(float)$p->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE date(created_at)='$date' AND status<>'Cancelado'")->fetchColumn();$movements=$p->query("SELECT * FROM cash_movements WHERE date(created_at)='$date' ORDER BY id DESC")->fetchAll();$netMov=array_sum(array_map(fn($x)=>$x['type']==='Entrada'?$x['amount']:-$x['amount'],$movements));page_head('Caixa');?>
<div class="card"><form><label>Data</label><input style="max-width:220px" type="date" name="date" value="<?=e($date)?>" onchange="this.form.submit()"></form></div><div class="grid g3"><div class="card kpi"><span>Vendas</span><strong><?=money($sales)?></strong></div><div class="card kpi"><span>Movimentos</span><strong><?=money($netMov)?></strong></div><div class="card kpi"><span>Esperado</span><strong><?=money($sales+$netMov)?></strong></div></div>
<div class="grid g2"><div class="card"><h2>Movimento de caixa</h2><form method="post"><?=csrf_field()?><input type="hidden" name="movement" value="1"><label>Tipo</label><select name="type"><option>Entrada</option><option>Saída</option></select><label>Descrição</label><input name="description"><label>Valor</label><input type="number" step=".01" name="amount"><label>Forma</label><input name="payment_method"><button class="primary">Registrar</button></form></div><div class="card"><h2>Fechamento</h2><form method="post"><?=csrf_field()?><input type="hidden" name="close" value="1"><label>Valor contado</label><input type="number" step=".01" name="counted"><label>Observações</label><textarea name="notes"></textarea><button class="gold">Fechar caixa</button></form></div></div><?php page_foot();?>